// CloudWatch Synthetics canary: probes HEALTHZ_URL from outside the monitored
// host (this runs as a managed Lambda, not on the EC2 instance). It proves
// external reachability that the in-cluster blackbox-exporter probe
// (deploy/blackbox/*, scraped from inside the same host) cannot.
//
// `Synthetics` and `SyntheticsLogger` are provided by the syn-nodejs-puppeteer
// Lambda runtime layer at execution time; they are not npm dependencies and
// are not installed here.
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const healthzCanary = async function () {
    const url = process.env.HEALTHZ_URL;
    if (!url) {
        throw new Error('HEALTHZ_URL environment variable is not set');
    }

    const page = await synthetics.getPage();
    const response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });

    if (!response) {
        throw new Error(`No response received from ${url}`);
    }
    if (response.status() !== 200) {
        throw new Error(`Unexpected status code ${response.status()} from ${url}`);
    }
    log.info(`healthzCanary: ${url} responded ${response.status()}`);
};

exports.handler = async () => {
    return await healthzCanary();
};
